action.command:
cd /workspace && node -e "
const { createClient } = require('@supabase/supabase-js');
const supabase = createClient(
  process.env.SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);

async function check() {
  // Get ALL Kulturhuset events
  const { data: khEvents, count } = await supabase
    .from('events')
    .select('id, title_en, start_time, source, status', { count: 'exact' })
    .eq('source', 'kulturhuset');

  console.log('Kulturhuset count:', count);
  console.log('\nKulturhuset events:');
  khEvents?.forEach(e => console.log(' ', e.id.substring(0,8), e.title_en?.substring(0,40), e.start_time, e.status));

  // Check if they are published
  const { count: publishedCount } = await supabase
    .from('events')
    .select('id', { count: 'exact', head: true })
    .eq('source', 'kulturhuset')
    .eq('status', 'published');

  console.log('\nPublished Kulturhuset:', publishedCount);

  // Check the actual start_times
  console.log('\nKulturhuset start_times:');
  khEvents?.forEach(e => console.log(' ', e.start_time));
}

check().catch(console.error);
